function longestMirror(words: string[]): number {
  const waiting = new Map<string, number>();
  let total = 0;
  for (const w of words) {
    const rev = w[1] + w[0];
    const c = waiting.get(rev) ?? 0;
    if (c > 0) {
      total += 4;
      waiting.set(rev, c - 1);
    } else {
      waiting.set(w, (waiting.get(w) ?? 0) + 1);
    }
  }
  for (const [w, c] of waiting) {
    if (c > 0 && w[0] === w[1]) return total + 2;
  }
  return total;
}

