function longestMirror(words: string[]): number {
  const cnt = Array.from({ length: 26 }, () => new Array(26).fill(0));
  for (const w of words) cnt[w.charCodeAt(0) - 97][w.charCodeAt(1) - 97]++;
  let total = 0, center = false;
  for (let a = 0; a < 26; a++) {
    const d = cnt[a][a];
    total += Math.floor(d / 2) * 4;
    if (d % 2 === 1) center = true;
    for (let b = a + 1; b < 26; b++) total += Math.min(cnt[a][b], cnt[b][a]) * 4;
  }
  return total + (center ? 2 : 0);
}

